        --radius-lg: 24px;
        --radius-md: 18px;
        --radius-sm: 12px;
      }

      * {
        box-sizing: border-box;
      }

      html,
      body {
        margin: 0;
        min-height: 100%;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, rgba(79, 70, 229, 0.14), transparent 34%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
      }

      body {
        line-height: 1.5;
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        top: 1rem;
        left: 1rem;
        transform: translateY(-220%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--primary-strong);
        color: #fff;
        text-decoration: none;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        width: min(100%, 960px);
        margin: 0 auto;
        padding: 32px 20px 56px;
      }

      .hero {
        padding: 24px 0 20px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.4rem 0.8rem;
        border-radius: 999px;
        background: rgba(79, 70, 229, 0.08);
        color: var(--primary-strong);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      .hero h1 {
        margin: 1rem 0 0.75rem;
        font-size: clamp(2rem, 4vw, 3.5rem);
        line-height: 1.05;
      }

      .hero p {
        max-width: 42rem;
        margin: 0;
        color: var(--muted);
        font-size: 1.05rem;
      }

      .quiz-card {
        backdrop-filter: blur(14px);
        background: var(--surface);
        border: 1px solid rgba(255, 255, 255, 0.7);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        padding: clamp(1.25rem, 2.5vw, 2rem);
      }

      .quiz-meta {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin-bottom: 1.25rem;
      }

      .meta-chip {
        padding: 0.5rem 0.85rem;
        border-radius: 999px;
        background: #eef2ff;
        color: var(--primary-strong);
        font-size: 0.9rem;
        font-weight: 600;
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        padding: 1rem;
        border: 1px solid var(--line);
        border-radius: var(--radius-md);
        background: var(--surface-strong);
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-width: 0;
      }

      legend {
        width: 100%;
        margin-bottom: 0.5rem;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .question-copy {
        margin: 0 0 0.6rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .choice-list {
        display: grid;
        gap: 0.75rem;
      }

      .choice {
        position: relative;
      }

      .choice input[type="checkbox"] {
        position: absolute;
        inset: 0 auto auto 0;
        width: 1.4rem;
        height: 1.4rem;
        margin: 1rem 0 0 1rem;
        accent-color: var(--primary);
      }

      .choice label {
        display: block;
        padding: 0.95rem 1rem 0.95rem 3rem;
        border: 1px solid var(--line);
        border-radius: var(--radius-sm);
        background: #fbfcff;
        cursor: pointer;
        font-weight: 500;
        transition:
          border-color 0.18s ease,
          box-shadow 0.18s ease,
          transform 0.18s ease,
          background-color 0.18s ease;
      }

      .choice label:hover {
        border-color: rgba(79, 70, 229, 0.45);
        transform: translateY(-1px);
      }

      .choice input[type="checkbox"]:focus-visible + label {
        outline: 3px solid rgba(79, 70, 229, 0.26);
        outline-offset: 3px;
        border-color: var(--primary);
      }

      .choice input[type="checkbox"]:checked + label {
        border-color: rgba(79, 70, 229, 0.55);
        background: rgba(79, 70, 229, 0.08);
        box-shadow: inset 0 0 0 1px rgba(79, 70, 229, 0.14);
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 1rem;
        margin-top: 0.5rem;
      }

      .button-primary {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
        color: #fff;
        padding: 0.95rem 1.4rem;
        font-size: 1rem;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(79, 70, 229, 0.26);
      }

      .button-primary:hover {
        filter: brightness(1.03);
      }

      .button-primary:focus-visible {
        outline: 3px solid rgba(79, 70, 229, 0.26);
        outline-offset: 4px;
      }

      .status {
        min-height: 1.5rem;
        color: var(--muted);
        font-weight: 600;
      }

      .status.error {
        color: var(--danger);
      }

      .error-banner {
        margin: 0 0 1rem;
        padding: 0.85rem 1rem;
        border: 1px solid #f7c3be;
        border-radius: var(--radius-sm);
        background: var(--danger-bg);
        color: var(--danger);
        font-weight: 600;
      }

      .field-error {
        margin: 0.75rem 0 0;
        color: var(--danger);
        font-weight: 600;
      }

      .footer-note {
        margin-top: 1.25rem;
        color: var(--muted);
        font-size: 0.92rem;
      }

      @media (max-width: 640px) {
        .page-shell {
          padding-inline: 16px;
        }

        .quiz-card {
          padding: 1rem;
        }

        .form-field {
          padding: 0.9rem;
        }

        .choice label {
          padding-right: 0.85rem;
        }
      }

      @media (forced-colors: active) {
        .quiz-card,
        .form-field,
        .choice label,
        .meta-chip,
        .eyebrow {
          border: 1px solid CanvasText;
        }

        .button-primary,
        .skip-link {
          border: 1px solid ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="app"></div>
    <script>
      const quizQuestions = [
        {
          id: "question-1",
          name: "language-family",
          title: "1. Which of these are programming languages?",
          helpText: "Choose every option that is considered a programming language.",
          options: [
            { id: "q1-python", value: "Python", label: "Python" },
            { id: "q1-html", value: "HTML", label: "HTML" },
            { id: "q1-rust", value: "Rust", label: "Rust" },
            { id: "q1-spanish", value: "Spanish", label: "Spanish" }
          ]
        },
        {
          id: "question-2",
          name: "compiled-languages",
          title: "2. Which languages are commonly compiled before running?",
          options: [
            { id: "q2-cpp", value: "C++", label: "C++" },
            { id: "q2-java", value: "Java", label: "Java" },
            { id: "q2-javascript", value: "JavaScript", label: "JavaScript" },
            { id: "q2-go", value: "Go", label: "Go" }
          ]
        },
        {
          id: "question-3",
          name: "web-languages",
          title: "3. Which technologies are core to front-end web development?",
          options: [
            { id: "q3-css", value: "CSS", label: "CSS" },
            { id: "q3-javascript", value: "JavaScript", label: "JavaScript" },
            { id: "q3-sql", value: "SQL", label: "SQL" },
            { id: "q3-html", value: "HTML", label: "HTML" }
          ]
        }
      ];

      const selections = {};

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function CheckboxChoice(question, option) {
        return `
          <div class="choice">
            <input
              id="${escapeHtml(option.id)}"
              name="${escapeHtml(question.name)}"
              type="checkbox"
              value="${escapeHtml(option.value)}"
            />
            <label for="${escapeHtml(option.id)}">${escapeHtml(option.label)}</label>
          </div>
        `;
      }

      function QuestionCard(question, index, errors) {
        const helpId = question.helpText ? `${question.id}-help` : "";
        const errorId = `${question.id}-error`;
        const describedBy = [helpId, errors[question.id] ? errorId : ""].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <fieldset ${describedBy ? `aria-describedby="${describedBy}"` : ""}>
              <legend>${escapeHtml(question.title)}</legend>
              ${
                question.helpText
                  ? `<p class="question-copy" id="${helpId}">${escapeHtml(question.helpText)}</p>`
                  : `<p class="question-copy">Select all answers that apply.</p>`
              }
              <div class="choice-list">
                ${question.options.map((option) => CheckboxChoice(question, option)).join("")}
              </div>
              ${
                errors[question.id]
                  ? `<p class="field-error" id="${errorId}">Error: Select at least one answer for question ${index + 1}.</p>`
                  : ""
              }
            </fieldset>
          </div>
        `;
      }

      function QuizForm(errors, globalMessage) {
        const hasErrors = Object.keys(errors).length > 0;
        return `
          <form id="quiz-form" novalidate>
            ${
              hasErrors
                ? '<div class="error-banner" role="alert">Please answer each question before submitting.</div>'
                : ""
            }
            ${quizQuestions.map((question, index) => QuestionCard(question, index, errors)).join("")}
            <div class="actions">
              <button class="button-primary" type="submit">Submit quiz</button>
              <div class="status ${globalMessage.type}" aria-live="polite">${escapeHtml(globalMessage.text)}</div>
            </div>
          </form>
        `;
      }

      function App(state) {
        return `
          <header class="page-shell hero">
            <div class="eyebrow">Interactive quiz</div>
            <h1>Computer languages knowledge check</h1>
            <p>
              Explore three multi-select questions about programming and web languages. Each answer
              uses accessible native checkboxes so learners can review and submit with confidence.
            </p>
          </header>
          <main class="page-shell" id="maincontent" tabindex="-1">
            <section class="quiz-card" aria-labelledby="quiz-heading">
              <div class="quiz-meta" aria-hidden="true">
                <div class="meta-chip">3 questions</div>
                <div class="meta-chip">Multiple answers allowed</div>
                <div class="meta-chip">Standalone HTML</div>
              </div>
              <h2 id="quiz-heading">Quiz form</h2>
              ${QuizForm(state.errors, state.message)}
              <p class="footer-note">Tip: Use Tab to move through answers and Space to select each checkbox.</p>
            </section>
          </main>
        `;
      }

      const state = {
        errors: {},
        message: { text: "", type: "" }
      };

      function readSelections() {
        const results = {};

        quizQuestions.forEach((question) => {
          const checked = Array.from(
            document.querySelectorAll(`input[name="${question.name}"]:checked`)
          ).map((input) => input.value);
          results[question.id] = checked;
        });

        return results;
      }

      function render() {
        const root = document.getElementById("app");
        root.innerHTML = App(state);

        const form = document.getElementById("quiz-form");
        form.addEventListener("submit", handleSubmit);
      }

      function handleSubmit(event) {
        event.preventDefault();
        Object.assign(selections, readSelections());

        const nextErrors = {};
        quizQuestions.forEach((question) => {
          if (!selections[question.id] || selections[question.id].length === 0) {
            nextErrors[question.id] = true;
          }
        });

        state.errors = nextErrors;

        if (Object.keys(nextErrors).length > 0) {
          state.message = {
            text: "Add at least one answer to every question.",
            type: "error"
          };
          render();
          const firstInvalid = document.querySelector(
            `input[name="${quizQuestions.find((question) => nextErrors[question.id]).name}"]`
          );
          if (firstInvalid) {
            firstInvalid.focus();
          }
          return;
        }

        state.message = {
          text: "Quiz submitted successfully. Your selections have been captured.",
          type: ""
        };
        render();
      }

      render();
    </script>
  </body>
</html>
