383.               ${
384.                 question.helpText
385.                   ? `<p class="question-copy" id="${helpId}">${escapeHtml(question.helpText)}</p>`
386.                   : `<p class="question-copy">Select all answers that apply.</p>`
387.               }
388.               <div class="choice-list">
389.                 ${question.options.map((option) => CheckboxChoice(question, option)).join("")}
390.               </div>
391.               ${
392.                 errors[question.id]
393.                   ? `<p class="field-error" id="${errorId}">Error: Select at least one answer for question ${index + 1}.</p>`
394.                   : ""
