          ]
        }
      ];

      const selections = {};

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function CheckboxChoice(question, option) {
        const isChecked = (selections[question.id] || []).includes(option.value);
        return `
          <div class="choice">
            <input
              id="${escapeHtml(option.id)}"
              name="${escapeHtml(question.name)}"
              type="checkbox"
              value="${escapeHtml(option.value)}"
              ${isChecked ? "checked" : ""}
            />
            <label for="${escapeHtml(option.id)}">${escapeHtml(option.label)}</label>
          </div>
        `;
      }

      function QuestionCard(question, index, errors) {
        const helpId = `${question.id}-help`;
        const errorId = `${question.id}-error`;
        const describedBy = [helpId, errors[question.id] ? errorId : ""].filter(Boolean).join(" ");
        const helpText = question.helpText || "Select all answers that apply.";

        return `
          <div class="form-field">
            <fieldset ${describedBy ? `aria-describedby="${describedBy}"` : ""}>
              <legend>${escapeHtml(question.title)}</legend>
              <p class="question-copy" id="${helpId}">${escapeHtml(helpText)}</p>
              <div class="choice-list">
                ${question.options.map((option) => CheckboxChoice(question, option)).join("")}
              </div>
              ${
                errors[question.id]
                  ? `<p class="field-error" id="${errorId}">Error: Select at least one answer for question ${index + 1}.</p>`
                  : ""
              }
            </fieldset>
          </div>
        `;
      }

      function QuizForm(errors, globalMessage) {
        const hasErrors = Object.keys(errors).length > 0;
        return `
          <form id="quiz-form" novalidate>
            ${
              hasErrors
                ? '<div class="error-banner" role="alert">Please answer each question before submitting.</div>'
                : ""
            }
            ${quizQuestions.map((question, index) => QuestionCard(question, index, errors)).join("")}
            <div class="actions">
              <button class="button-primary" type="submit">Submit quiz</button>
              <div class="status ${globalMessage.type}" role="status" aria-live="polite">${escapeHtml(globalMessage.text)}</div>
            </div>
          </form>
        `;
      }

      function App(state) {
        return `
          <header class="page-shell hero">
            <div class="eyebrow">Interactive quiz</div>
            <h1>Computer languages knowledge check</h1>
            <p>
              Explore three multi-select questions about programming and web languages. Each answer
              uses accessible native checkboxes so learners can review and submit with confidence.
            </p>
          </header>
          <main class="page-shell" id="maincontent" tabindex="-1">
            <section class="quiz-card" aria-labelledby="quiz-heading">
              <div class="quiz-meta" aria-hidden="true">
                <div class="meta-chip">3 questions</div>
                <div class="meta-chip">Multiple answers allowed</div>
                <div class="meta-chip">Standalone HTML</div>
              </div>
              <h2 id="quiz-heading">Quiz form</h2>
              ${QuizForm(state.errors, state.message)}
              <p class="footer-note">Tip: Use Tab to move through answers and Space to select each checkbox.</p>
            </section>
          </main>
        `;
      }

      const state = {
        errors: {},
        message: { text: "", type: "" }
      };

      function readSelections() {
        const results = {};

        quizQuestions.forEach((question) => {
          const checked = Array.from(
            document.querySelectorAll(`input[name="${question.name}"]:checked`)
          ).map((input) => input.value);
          results[question.id] = checked;
        });

        return results;
      }

      function render() {
        const root = document.getElementById("app");
        root.innerHTML = App(state);

        const form = document.getElementById("quiz-form");
        form.addEventListener("submit", handleSubmit);
      }

      function handleSubmit(event) {
        event.preventDefault();
        Object.assign(selections, readSelections());

        const nextErrors = {};
        quizQuestions.forEach((question) => {
          if (!selections[question.id] || selections[question.id].length === 0) {
            nextErrors[question.id] = true;
          }
        });

        state.errors = nextErrors;

        if (Object.keys(nextErrors).length > 0) {
          state.message = {
            text: "Add at least one answer to every question.",
            type: "error"
          };
          render();
          const firstInvalid = document.querySelector(
            `input[name="${quizQuestions.find((question) => nextErrors[question.id]).name}"]`
          );
          if (firstInvalid) {
            firstInvalid.focus();
          }
          return;
        }

        state.message = {
          text: "Quiz submitted successfully. Your selections have been captured.",
          type: ""
        };
        render();
      }

      render();
    </script>
  </body>
</html>
